effect.shader:
out highp vec4 vs_COLOR0;
out highp vec2 acScreenNorm;
out highp float vs_TEXCOORD1;
out highp vec4 vs_TEXCOORD2;
highp vec3 vs_TEXCOORD3;
out highp vec4 vs_TEXCOORD5;
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec3 u_xlatb2;
vec4 u_xlat3;
mediump vec3 u_xlat16_4;
mediump vec3 u_xlat16_5;
float u_xlat18;
bool u_xlatb18;
float u_xlat19;
void main()
{
    u_xlat0.xy = in_POSITION0.xy + vec2(_VertexOffsetX, _VertexOffsetY);
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat1 = hlslcc_mtx4x4unity_ObjectToWorld[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat1;
    u_xlat2 = u_xlat1 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1.xyz = hlslcc_mtx4x4unity_ObjectToWorld[3].xyz * in_POSITION0.www + u_xlat1.xyz;
    u_xlat1.xyz = (-u_xlat1.xyz) + _WorldSpaceCameraPos.xyz;
    u_xlat3 = u_xlat2.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat3 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat2.xxxx + u_xlat3;
    u_xlat3 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat2.zzzz + u_xlat3;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat2.wwww + u_xlat3;
    u_xlat16_4.xyz = in_COLOR0.xyz * vec3(0.265884995, 0.265884995, 0.265884995) + vec3(0.736584008, 0.736584008, 0.736584008);
    u_xlat16_4.xyz = in_COLOR0.xyz * u_xlat16_4.xyz + vec3(-0.00980184041, -0.00980184041, -0.00980184041);
    u_xlat16_4.xyz = in_COLOR0.xyz * u_xlat16_4.xyz + vec3(0.00319697009, 0.00319697009, 0.00319697009);
    u_xlat16_5.xyz = in_COLOR0.xyz * vec3(0.0849710032, 0.0849710032, 0.0849710032) + vec3(-0.000163029006, -0.000163029006, -0.000163029006);
    u_xlatb2.xyz = lessThan(in_COLOR0.xyzx, vec4(0.0725490004, 0.0725490004, 0.0725490004, 0.0)).xyz;
    {
        vec3 hlslcc_movcTemp = u_xlat16_4;
        hlslcc_movcTemp.x = (u_xlatb2.x) ? u_xlat16_5.x : u_xlat16_4.x;
        hlslcc_movcTemp.y = (u_xlatb2.y) ? u_xlat16_5.y : u_xlat16_4.y;
        hlslcc_movcTemp.z = (u_xlatb2.z) ? u_xlat16_5.z : u_xlat16_4.z;
        u_xlat16_4 = hlslcc_movcTemp;
    }
    vs_COLOR0.xyz = (int(_UIVertexColorAlwaysGammaSpace) != 0) ? u_xlat16_4.xyz : in_COLOR0.xyz;
    vs_COLOR0.w = in_COLOR0.w;
    u_xlatb18 = 0.0>=in_TEXCOORD0.w;
    u_xlat18 = u_xlatb18 ? 1.0 : float(0.0);
    u_xlat19 = (-_WeightNormal) + _WeightBold;
    u_xlat18 = u_xlat18 * u_xlat19 + _WeightNormal;
    u_xlat18 = u_xlat18 * 0.25 + _FaceDilate;
    u_xlat18 = u_xlat18 * _ScaleRatioA;
    vs_TEXCOORD1 = u_xlat18 * 0.5;
    acScreenNorm.xy = in_TEXCOORD0.xy;
    u_xlat0.z = in_POSITION0.w;
    u_xlat0.y = u_xlat0.y * _ProjectionParams.x;
    u_xlat0.xzw = u_xlat0.xzy * vec3(0.5, 0.5, 0.5);
    vs_TEXCOORD2.xy = u_xlat0.zz + u_xlat0.xw;
    vs_TEXCOORD2.zw = in_POSITION0.zw;
    u_xlat0.xyz = u_xlat1.yyy * hlslcc_mtx4x4_EnvMatrix[1].xyz;
    u_xlat0.xyz = hlslcc_mtx4x4_EnvMatrix[0].xyz * u_xlat1.xxx + u_xlat0.xyz;
    vs_TEXCOORD3.xyz = hlslcc_mtx4x4_EnvMatrix[2].xyz * u_xlat1.zzz + u_xlat0.xyz;
    vs_TEXCOORD5.xy = in_TEXCOORD1.xy * _FaceTex_ST.xy + _FaceTex_ST.zw;
    vs_TEXCOORD5.zw = in_TEXCOORD1.xy * _OutlineTex_ST.xy + _OutlineTex_ST.zw;
    return;
}

#endif
#ifdef FRAGMENT

vec4 u_xlat0;
mediump vec4 u_xlat16_0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec4 u_xlat2;
bool u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
mediump float u_xlat16_5;
mediump vec3 u_xlat16_6;
float u_xlat7;
vec3 u_xlat8;
vec2 u_xlat9;
mediump float u_xlat16_12;
float u_xlat14;
mediump float u_xlat16_19;
float u_xlat21;
void main()
{
    u_xlat0.x = texture(inputImg, acScreenNorm.xy).w;
    u_xlat7 = dFdx(acScreenNorm.y);
    u_xlat14 = dFdy(acScreenNorm.y);
    u_xlat7 = abs(u_xlat14) + abs(u_xlat7);
    u_xlat7 = u_xlat7 * _TextureHeight;
    u_xlat7 = u_xlat7 * 0.75;
    u_xlat7 = float(1.0) / u_xlat7;
    u_xlat7 = u_xlat7 * _GradientScale;
    u_xlat14 = _Sharpness + 1.0;
    u_xlat7 = u_xlat14 * u_xlat7;
    u_xlat14 = (-vs_TEXCOORD1) + 0.5;
    u_xlat21 = 0.5 / u_xlat7;
    u_xlat14 = u_xlat21 + u_xlat14;
    u_xlat0.x = (-u_xlat0.x) + u_xlat14;
    u_xlat14 = _OutlineWidth * _ScaleRatioA;
    u_xlat14 = u_xlat7 * u_xlat14;
    u_xlat21 = _OutlineSoftness * _ScaleRatioA;
    u_xlat1.x = u_xlat7 * u_xlat21;
    u_xlat8.xyz = vs_COLOR0.xyz * _FaceColor.xyz;
    u_xlat2.xy = vec2(_FaceUVSpeedX, _FaceUVSpeedY) * _Time.yy + vs_TEXCOORD5.xy;
    u_xlat2 = texture(FaceTex, u_xlat2.xy);
    u_xlat8.xyz = u_xlat8.xyz * u_xlat2.xyz;
    u_xlat2.x = u_xlat2.w * _FaceColor.w;
    u_xlat9.xy = vec2(_OutlineUVSpeedX, _OutlineUVSpeedY) * _Time.yy + vs_TEXCOORD5.zw;
    u_xlat3 = texture(OutlineTex, u_xlat9.xy);
    u_xlat4 = u_xlat3 * _OutlineColor;
    u_xlat16_5 = u_xlat14 * 0.5;
    u_xlat16_12 = u_xlat0.x * u_xlat7 + (-u_xlat16_5);
    u_xlat16_12 = u_xlat1.x * 0.5 + u_xlat16_12;
    u_xlat16_19 = u_xlat21 * u_xlat7 + 1.0;
    u_xlat16_12 = u_xlat16_12 / u_xlat16_19;
    u_xlat16_12 = clamp(u_xlat16_12, 0.0, 1.0);
    u_xlat16_12 = (-u_xlat16_12) + 1.0;
    u_xlat16_5 = u_xlat0.x * u_xlat7 + u_xlat16_5;
    u_xlat16_5 = clamp(u_xlat16_5, 0.0, 1.0);
    u_xlat16_19 = min(u_xlat14, 1.0);
    u_xlat16_19 = sqrt(u_xlat16_19);
    u_xlat16_5 = u_xlat16_19 * u_xlat16_5;
    u_xlat16_6.xyz = u_xlat8.xyz * u_xlat2.xxx;
    u_xlat16_0.xyz = u_xlat4.xyz * u_xlat4.www + (-u_xlat16_6.xyz);
    u_xlat16_0.w = _OutlineColor.w * u_xlat3.w + (-u_xlat2.x);
    u_xlat16_0 = u_xlat16_0 * vec4(u_xlat16_5);
    u_xlat16_1.xyz = u_xlat8.xyz * u_xlat2.xxx + u_xlat16_0.xyz;
    u_xlat16_1.w = _FaceColor.w * u_xlat2.w + u_xlat16_0.w;
    u_xlat16_0 = vec4(u_xlat16_12) * u_xlat16_1;
    u_xlatb2 = 0<_fill_texture;
    if(u_xlatb2){
        u_xlat1 = texture(source_rt, vs_TEXCOORD2.xy);
        u_xlat0 = u_xlat16_0 * u_xlat1;
        u_xlat16_0 = u_xlat0;
    }
    u_xlat0 = u_xlat16_0 * vs_COLOR0.wwww;
    fragColor = u_xlat0;
    return;
}

#endif
